{"code_block": "import PyPDF2, re
pdf_path = '/home/user/ipcc_85.pdf'
reader = PyPDF2.PdfReader(pdf_path)
nuclear_pages = []
energy_keywords = ['energy', 'power', 'electricity', 'reactor', 'nuclear energy', 'nuclear power']
for i, page in enumerate(reader.pages):
    try:
        text = page.extract_text()
    except Exception as e:
        text = ''
    if not text:
        continue
    txt = text.lower()
    if 'nuclear' in txt:
        # check if any keyword also present to indicate energy context
        if any(keyword in txt for keyword in energy_keywords):
            nuclear_pages.append(i+1)  # page numbers are 1-indexed
print('Pages mentioning nuclear (with energy keywords):', nuclear_pages)
print('Count:', len(nuclear_pages))
